//! The shapes the knowledge base sends and accepts. TypeScript bindings are generated by `cargo test`.

use hub_core::diff::DiffLine;
use hub_core::{double_option, Id, IssueRow};
use serde::{Deserialize, Serialize};
use ts_rs::TS;

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct WikiSpace {
    pub id: Id,
    pub key: String,
    pub name: String,
    pub description: String,
    pub project_id: Option<Id>,
    pub project_key: Option<String>,
    /// `local`, or the system the space mirrors (`confluence`).
    pub source: String,
    pub created_at: String,
    pub page_count: i64,
    /// Whether the caller may create, edit and delete pages here.
    pub can_edit: bool,
    /// Whether the caller may delete the space or bind it to another project.
    pub can_admin: bool,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct WikiTreeNode {
    pub id: Id,
    pub parent_id: Option<Id>,
    pub title: String,
    pub position: i64,
    pub updated_at: String,
    pub locked: bool,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct WikiPage {
    pub id: Id,
    pub space_id: Id,
    pub space_key: String,
    pub parent_id: Option<Id>,
    pub title: String,
    /// Markdown.
    pub body: String,
    pub position: i64,
    pub version: i64,
    pub author_id: Option<Id>,
    pub updated_by: Option<Id>,
    pub created_at: String,
    pub updated_at: String,
    /// The page's id in the system it was imported from.
    pub source_id: Option<String>,
    pub source_version: Option<i64>,
    pub source_url: Option<String>,
    /// A locked page mirrors its source and cannot be edited until it is detached.
    pub locked: bool,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct WikiPageRef {
    pub id: Id,
    pub title: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct WikiBacklink {
    pub page_id: Id,
    pub space_key: String,
    pub title: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct WikiPageIssue {
    /// `mentions` when the body names the issue, `documents` when it was linked by hand.
    pub relation: String,
    pub issue: IssueRow,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct WikiPageDetail {
    #[serde(flatten)]
    pub page: WikiPage,
    pub space: WikiSpace,
    /// The ancestors, outermost first; the page itself is not included.
    pub breadcrumbs: Vec<WikiPageRef>,
    pub children: Vec<WikiTreeNode>,
    pub issues: Vec<WikiPageIssue>,
    /// Pages whose body links here with `[[Title]]`.
    pub backlinks: Vec<WikiBacklink>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct WikiRevisionInfo {
    pub version: i64,
    pub title: String,
    pub author_id: Option<Id>,
    /// Who saved it when no user did, e.g. "Confluence".
    pub author_label: Option<String>,
    pub message: String,
    pub created_at: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct WikiRevision {
    #[serde(flatten)]
    pub info: WikiRevisionInfo,
    pub body: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct WikiDiff {
    pub from: i64,
    pub to: i64,
    pub from_title: String,
    pub to_title: String,
    pub lines: Vec<DiffLine>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct WikiSearchHit {
    pub page_id: Id,
    pub space_key: String,
    pub title: String,
    /// An excerpt of the body; the matched words stand between `<mark>` and `</mark>`.
    pub snippet: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct WikiTemplate {
    pub id: String,
    pub name: String,
    pub description: String,
    pub body: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct WikiIssuePage {
    pub page_id: Id,
    pub space_key: String,
    pub title: String,
    pub relation: String,
    pub updated_at: String,
}

/// The knowledge base's panel on an issue page (`issue.panels.wiki`).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct WikiIssuePanel {
    pub pages: Vec<WikiIssuePage>,
}

#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct WikiTasksResult {
    /// The keys of the created issues, in the order of the lines.
    pub keys: Vec<String>,
    pub page: WikiPageDetail,
}

#[derive(Debug, Clone, Default, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, optional_fields)]
pub struct WikiNewSpace {
    pub key: String,
    pub name: String,
    pub description: Option<String>,
    /// Binds the space to a project: it is then visible and editable as that project is.
    pub project_key: Option<String>,
}

#[derive(Debug, Clone, Default, Deserialize, TS)]
#[serde(rename_all = "camelCase", default)]
#[ts(export, optional_fields)]
pub struct WikiSpacePatch {
    pub name: Option<String>,
    pub description: Option<String>,
    /// A project key binds the space, `null` unbinds it, absent leaves the binding alone.
    #[serde(deserialize_with = "double_option")]
    #[ts(optional, type = "string | null")]
    pub project_key: Option<Option<String>>,
}

#[derive(Debug, Clone, Default, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, optional_fields)]
pub struct WikiNewPage {
    pub title: String,
    pub body: Option<String>,
    pub parent_id: Option<Id>,
    /// Starts the page from a built-in template when no body is given.
    pub template_id: Option<String>,
}

#[derive(Debug, Clone, Default, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, optional_fields)]
pub struct WikiPagePatch {
    pub title: Option<String>,
    pub body: Option<String>,
    /// The version the edit started from; the save is refused when somebody saved in between.
    pub base_version: i64,
    pub message: Option<String>,
}

#[derive(Debug, Clone, Default, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct WikiMove {
    pub parent_id: Option<Id>,
    /// The index among the new siblings, from 0.
    pub position: i64,
}

#[derive(Debug, Clone, Default, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct WikiRestore {
    pub version: i64,
}

#[derive(Debug, Clone, Default, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, optional_fields)]
pub struct WikiTasksRequest {
    pub project_key: String,
    pub type_id: Option<Id>,
    /// Indexes of task lines in the body split on `\n`, from 0.
    pub lines: Vec<usize>,
    /// When given, the request is refused if the page has moved on from this version.
    pub base_version: Option<i64>,
}
